CREATE TABLE rc_o(id int, s text); CREATE TABLE rc_i(v int, t text);
INSERT INTO rc_o VALUES (1,'a'),(2,'b'),(3,NULL); INSERT INTO rc_i VALUES (1,'a'),(2,'x');
SELECT id FROM rc_o WHERE (id, 1) = (SELECT v, 1 FROM rc_i WHERE v = rc_o.id) ORDER BY id;
SELECT id, (id, s) = (SELECT v, t FROM rc_i WHERE v = rc_o.id) FROM rc_o ORDER BY id;
SELECT id, (id, s) <> (SELECT v, t FROM rc_i WHERE v = rc_o.id) FROM rc_o ORDER BY id;
SELECT id FROM rc_o WHERE (id, 1) = (SELECT v, 1 FROM rc_i WHERE v = 1) ORDER BY id;
SELECT id FROM rc_o WHERE ROW(id, 1) < (SELECT v, 2 FROM rc_i WHERE v = rc_o.id) ORDER BY id;
SELECT id, ROW(id, 'b') >= (SELECT 2, 'a') FROM rc_o ORDER BY id;
SELECT (1, 2) = (SELECT v, v FROM rc_i);
SELECT (1, 2) = (SELECT v FROM rc_i WHERE v = 1);
SELECT (1, 2) = (SELECT v, v, v FROM rc_i WHERE v = 1);
SELECT (1, 2) = (SELECT 1, 2 WHERE false);
SELECT id FROM rc_o WHERE id > 5 AND (id, 1) = (SELECT 1/0, 1);
SELECT (1, '2') = (1, 2);
SELECT (1, 'zz') = (1, 2);
SELECT ('1', 2) < (2, 2);
SELECT (1, '2') = (SELECT 1, 2);
SELECT (1, 'zz') = (SELECT 1, 2);
SELECT ('a', 'b') = ('a', 'b');
SELECT (1, '2') <> (1, 3);
SELECT ROW(1, NULL) = ROW(1, '2');
CREATE TABLE rc_c(a text COLLATE "C", b text COLLATE "POSIX", n int);
INSERT INTO rc_c VALUES ('a','b',1),(NULL,'b',2),('a',NULL,3);
SELECT n, a = b FROM rc_c ORDER BY n;
SELECT n, a < b FROM rc_c WHERE n = 2;
SELECT n FROM rc_c WHERE a COLLATE "C" = b COLLATE "POSIX";
SELECT n, a = 'a', 'a' = b FROM rc_c ORDER BY n;
